pub fn run(grid: *const Grid, min_points: usize) []i64 {
    const labels = d.alloc(i64, grid.neighbors.len);
    @memset(labels, -2);
    var cluster: i64 = 0;
    for (0..labels.len) |p| {
        if (labels[p] != -2) continue;
        if (grid.neighbors[p].len < min_points) {
            labels[p] = -1;
            continue;
        }
        labels[p] = cluster;
        var queue: std.ArrayList(usize) = .empty;
        for (grid.neighbors[p]) |id| d.append(usize, &queue, id);
        var front: usize = 0;
        while (front < queue.items.len) : (front += 1) {
            const q = queue.items[front];
            if (labels[q] == -1) {
                labels[q] = cluster;
                continue;
            }
            if (labels[q] >= 0) continue;
            labels[q] = cluster;
            if (grid.neighbors[q].len >= min_points) for (grid.neighbors[q]) |id| d.append(usize, &queue, id);
        }
        cluster += 1;
    }
    return labels;
fn extraction(optics: Optics, radius: i64) []i64 {
    const labels = d.alloc(i64, optics.order.len);
    var cluster: i64 = -1;
    const threshold = radius * radius;
    for (optics.order) |id| {
        if (optics.reach[id] > threshold) {
            if (optics.core[id] <= threshold) {
                cluster += 1;
                labels[id] = cluster;
            } else labels[id] = -1;
        } else labels[id] = cluster;
    }
    return labels;
